'use strict';
const {comparisons,supportedChangeQuote}=require('./image-claims');

// Quotes are selected from the original transcript, never regenerated by the model.
// Short sentences/clauses also let the coach quote a useful edit without rewriting
// punctuation or accidentally correcting the words used as evidence.
function excerpts(text){
  const quotes=new Set();
  function add(value){
    value=value.trim();if(!value)return;
    while(value.length>480){
      const boundary=value.lastIndexOf(' ',480),end=boundary>0?boundary:480;
      quotes.add(value.slice(0,end));value=value.slice(end).trim();
    }
    if(value)quotes.add(value);
  }
  add(text); // Retain excerpts covering the whole response, including its ending.
  const sentences=new Intl.Segmenter('en',{granularity:'sentence'}).segment(text);
  for(const {segment} of sentences){add(segment);for(const clause of segment.split(/[,;:\n]|(?=\b(?:whereas|while|however|although|despite)\b)/i))add(clause)}
  return [...quotes].slice(0,256);
}
function contract(mapping,text){
  const quotes=excerpts(text);
  const supportedChangeQuotes=quotes.filter(q=>supportedChangeQuote(mapping,q));
  const inaccurateQuotes=quotes.filter(q=>!supportedChangeQuotes.includes(q));
  return {
    facts:mapping.facts.map((fact,factIndex)=>({factIndex,fact})),
    quotes,comparisons:comparisons(mapping),supportedChangeQuotes,inaccurateQuotes,
    definitions:{
      learnerQuote:{type:'string',enum:quotes},
      ...(inaccurateQuotes.length?{inaccurateQuote:{type:'string',enum:inaccurateQuotes}}:{}),
      factIndex:{type:'integer',enum:mapping.facts.map((_,i)=>i)}
    }
  };
}
const quote={$ref:'#/$defs/learnerQuote'},inaccurateQuote={$ref:'#/$defs/inaccurateQuote'},index={$ref:'#/$defs/factIndex'};
const references=(max,min=0)=>({type:'array',items:index,minItems:min,maxItems:max});
const object=properties=>({type:'object',properties,required:Object.keys(properties),additionalProperties:false});
function coachingSchema(base,mapping,text){
  const s=structuredClone(base),c=contract(mapping,text);s.$defs=c.definitions;
  s.properties.strength.anyOf[0].properties.quote=quote;
  s.properties.changes.maxItems=2;
  s.properties.changes.items.properties.quote=quote;
  s.properties.changes.items.properties.factIndices=references(mapping.facts.length);
  const strength=s.properties.strength,changes=s.properties.changes;
  // Readiness is derived from meaningful edits; optional refinements may remain.
  // Every review still needs a quoted strength or an edit.
  const review={anyOf:[
    object({strength:strength.anyOf[0],changes:{...changes,maxItems:0}}),
    object({strength,changes:{...changes,minItems:1}})
  ]};
  delete s.properties.strength;delete s.properties.changes;delete s.properties.ready;
  s.properties={review,...s.properties};s.required=Object.keys(s.properties);
  s.properties.rewriteFactIndices=references(mapping.facts.length,1);
  // Required per-fact keys prevent omitted, duplicated or reordered coverage.
  s.properties.coverage=object(Object.fromEntries(mapping.facts.map((_,i)=>[String(i),{anyOf:[
    object({status:{type:'string',enum:['covered','partial']},evidence:quote,feedback:{type:'string'}}),
    ...(c.inaccurateQuotes.length?[object({status:{type:'string',enum:['inaccurate']},evidence:inaccurateQuote,feedback:{type:'string'}})]:[]),
    object({status:{type:'string',enum:['missing']},evidence:{type:'string',enum:['']},feedback:{type:'string'}})
  ]}])));
  return s;
}
function contentSchema(base,mapping,text){
  const c=contract(mapping,text);
  const evidence=kinds=>object({quote,factIndices:references(mapping.facts.length,kinds.includes('generic')?0:1),kind:{type:'string',enum:kinds}});
  const supporting={anyOf:[evidence(['feature','relationship']),evidence(['generic'])]},branches=[];
  // A factual-error judgment must contain the actual inaccurate quote. Accurate
  // judgments cannot produce inaccurate evidence, and higher bands must provide
  // the kind of supporting evidence that the validator requires.
  for(const accuracy of c.inaccurateQuotes.length?['accurate','minor-errors','major-errors']:['accurate']){
    const groups=[[0],[1],[2,3],...(accuracy==='major-errors'?[[4]]:[[4,5],[6]])];
    for(const scores of groups){
      const required=scores[0]>=2,wrong=accuracy!=='accurate',count=Number(required)+Number(wrong);
      branches.push(object({
        score:{type:'integer',enum:scores},
        relevance:{type:'string',enum:scores[0]===0?['image-specific','limited','irrelevant']:scores[0]===1?['image-specific','limited']:['image-specific']},
        accuracy:{type:'string',enum:[accuracy]},
        scoreImpact:scores[0]===6?{type:'null'}:object({kind:{type:'string',enum:['accuracy','main-feature','relationship','clarity','relevance']},quote,factIndices:references(mapping.facts.length,1),observation:{type:'string'},impact:{type:'string'}}),
        ...(required?{requiredEvidence:evidence(scores[0]>=4?['relationship']:['feature','relationship'])}:{}),
        ...(wrong?{inaccuracy:object({quote:inaccurateQuote,factIndices:references(mapping.facts.length,1)})}:{}),
        otherEvidence:{type:'array',minItems:count?0:1,maxItems:6-count,items:supporting}
      }));
    }
  }
  branches.push(object({score:{type:'null'},relevance:{type:'string',enum:['source-limited']},accuracy:{type:'string',enum:['unverifiable']},scoreImpact:{type:'null'},otherEvidence:{type:'array',minItems:1,maxItems:6,items:supporting}}));
  return {...object({judgment:{anyOf:branches},reason:structuredClone(base.properties.reason),nextStep:structuredClone(base.properties.nextStep)}),$defs:c.definitions};
}
function contentJudgment(data){
  if(!data?.judgment)return data;
  const j=data.judgment;
  return {score:j.score,relevance:j.relevance,accuracy:j.accuracy,...(Object.hasOwn(j,'scoreImpact')?{scoreImpact:j.scoreImpact}:{}),reason:data.reason,nextStep:data.nextStep,evidence:[
    ...(j.requiredEvidence?[j.requiredEvidence]:[]),
    ...(j.inaccuracy?[{...j.inaccuracy,kind:'inaccurate'}]:[]),
    ...(Array.isArray(j.otherEvidence)?j.otherEvidence:[])
  ]};
}
function normalizeReview(data){
  // Correct representation only. Never add a score, quote, reference or fact.
  if(!data||typeof data!=='object')return data;
  const out=structuredClone(data),refs=value=>Array.isArray(value)?[...new Set(value)]:value;
  if(Array.isArray(out.rewriteFactIndices))out.rewriteFactIndices=refs(out.rewriteFactIndices);
  const changes=out.review?.changes||out.changes;
  for(const change of Array.isArray(changes)?changes:[])if(change&&Array.isArray(change.factIndices))change.factIndices=refs(change.factIndices);
  const j=out.judgment||out;
  for(const e of [j.requiredEvidence,j.inaccuracy,j.scoreImpact,...(Array.isArray(j.otherEvidence)?j.otherEvidence:[]),...(Array.isArray(j.evidence)?j.evidence:[])])if(e&&Array.isArray(e.factIndices))e.factIndices=refs(e.factIndices);
  return out;
}
function coachingCoverage(data,mapping){
  if(data?.review&&typeof data.review==='object'){
    data={...data,strength:data.review.strength,changes:data.review.changes,ready:Array.isArray(data.review.changes)&&data.review.changes.every(c=>c.kind==='refinement')};
  }
  if(data?.coverage&&typeof data.coverage==='object'&&!Array.isArray(data.coverage)){
    data={...data,coverage:mapping.facts.map((_,factIndex)=>({...data.coverage[String(factIndex)],factIndex}))};
  }
  return data;
}
module.exports={excerpts,contract,coachingSchema,contentSchema,contentJudgment,coachingCoverage,normalizeReview};
